mapper.select:
SELECT history.id, history.case_id, history.case_timeline_status,
       history.description, history.created_at
FROM case_status_histories history
JOIN cases ON cases.id = history.case_id
WHERE history.case_id = #{caseId}
  AND cases.user_id = #{userId}
ORDER BY history.created_at DESC, history.id DESC
LIMIT #{limit, jdbcType=INTEGER} OFFSET #{offset}
